#!/usr/bin/env python3
import csv, gzip, io, json, sys, os
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def local_to_ts(naive, tz, fold=0):
    return int(naive.replace(tzinfo=tz, fold=fold).timestamp())


def std_offset(tz):
    for m in (1, 7, 4, 10):
        d = datetime(2026, m, 1, 12, tzinfo=tz)
        if not d.dst():
            return int(d.utcoffset().total_seconds())
    return int(datetime(2026, 1, 1, tzinfo=tz).utcoffset().total_seconds())


def parse_abbr(text, tz):
    out = []
    hdr = None
    for row in csv.reader(lines_of(text)):
        cells = [c.strip() for c in row]
        if 'Badge' in cells and 'Punch' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        mo, d, y = g('Date').split('/')
        t = g('Time').upper().split()
        hh, mm, ss = [int(x) for x in t[0].split(':')]
        if len(t) > 1:
            ap = t[1]
            hh = hh % 12 + (12 if ap == 'PM' else 0)
        naive = datetime(int(y), int(mo), int(d), hh, mm, ss)
        z = g('Zone').upper()
        fold = 0 if z.endswith('DT') else 1
        out.append((g('Record'), g('Badge'), g('Punch').upper(), local_to_ts(naive, tz, fold)))
    return out


def parse_epoch(text, tz):
    out = []
    schema = 1
    for l in lines_of(text):
        o = json.loads(l)
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            out.append((str(o['punch_id']), o['employee'], o['direction'].upper(), int(o['epoch_ms']) // 1000))
        else:
            if 'ts_ms' in o:
                ts = int(o['ts_ms']) // 1000
            else:
                ts = int(o['ts'])
            out.append((str(o['id']), o['emp'], o['dir'].upper(), ts))
    return out


def parse_offset(text, tz):
    out = []
    for row in csv.DictReader(io.StringIO('\n'.join(lines_of(text))), delimiter=';'):
        dt = datetime.fromisoformat(row['timestamp'].strip())
        ts = int(dt.timestamp())
        out.append((row['punch_id'], row['employee'], 'IN' if row['event'].strip() == 'clock_in' else 'OUT', ts))
    return out


def parse_legacy(text, tz):
    out = []
    std = std_offset(tz)
    off = std
    for l in lines_of(text):
        l = l.rstrip('\r\n')
        c = l[0]
        if c == 'H':
            s = l[13:18].strip()
            if s and s[0] in '+-' and len(s) == 5:
                v = (int(s[1:3]) * 3600 + int(s[3:5]) * 60)
                off = v if s[0] == '+' else -v
            else:
                off = std
        elif c == 'D':
            pid = l[1:9]
            badge = l[9:15].strip()
            d = l[16:30]
            naive = datetime(int(d[0:4]), int(d[4:6]), int(d[6:8]), int(d[8:10]), int(d[10:12]), int(d[12:14]))
            ts = int(naive.replace(tzinfo=UTC).timestamp()) - off
            out.append((pid, 'E' + badge, 'IN' if l[15] == 'I' else 'OUT', ts))
    return out


def parse_de(text, tz):
    out = []
    hdr = None
    for row in csv.reader(lines_of(text), delimiter='\t'):
        cells = [c.strip() for c in row]
        if 'Ausweis' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        d, mo, y = g('Datum').split('.')
        hh, mm = g('Uhrzeit').split(':')[:2]
        naive = datetime(int(y), int(mo), int(d), int(hh), int(mm))
        fold = 0 if g('Zeitzone').upper() == 'MESZ' else 1
        out.append((g('Nr'), g('Ausweis'), 'IN' if g('Buchung') == 'K' else 'OUT', local_to_ts(naive, tz, fold)))
    return out


def parse_local_csv(text, tz):
    out = []
    for row in csv.DictReader(io.StringIO('\n'.join(lines_of(text)))):
        naive = datetime.strptime(row['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((row['punch_ref'].strip(), row['employee_id'].strip(), row['direction'].strip().upper(),
                    local_to_ts(naive, tz, 0)))
    return out


def parse_local_jsonl(text, tz):
    out = []
    for l in lines_of(text):
        p = json.loads(l)['punch']
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], p['type'].upper(), local_to_ts(naive, tz, 0)))
    return out


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_local_csv,
           'local-jsonl': parse_local_jsonl}


def read_csv_file(path):
    return list(csv.DictReader(io.StringIO('\n'.join(lines_of(read_text(path))))))


def parse_utc(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_utc(period['corrections_cutoff'])
    sites = {r['site'].strip(): r for r in read_csv_file(os.path.join(inp, 'sites.csv'))}
    ztz = {s: ZoneInfo(r['timezone'].strip()) for s, r in sites.items()}
    emps = read_csv_file(os.path.join(inp, 'employees.csv'))
    emp_home = {r['employee_id'].strip(): r['home_site'].strip() for r in emps}
    rates = {}
    for r in read_csv_file(os.path.join(inp, 'rates.csv')):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Fraction(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    # 1 collect
    punches = {}  # (site,id) -> [emp, dir, ts]
    ever = set()
    for site in sorted(sites):
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        parser = PARSERS[sites[site]['format'].strip()]
        files = []
        for root, _, fs in os.walk(d):
            for f in fs:
                files.append(os.path.join(root, f))
        for path in sorted(files):
            for pid, emp, dr, ts in parser(read_text(path), ztz[site]):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp, dr, ts]

    # 2 corrections
    corrs = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, fs in os.walk(cdir):
            for f in fs:
                corrs += read_csv_file(os.path.join(root, f))
    corrs = [c for c in corrs if parse_utc(c['issued_at']) <= cutoff]
    corrs.sort(key=lambda c: (parse_utc(c['issued_at']), c['correction_id']))
    applied = 0
    for c in corrs:
        k = (c['site'].strip(), c['punch_id'].strip())
        a = c['action'].strip().lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = int(parse_utc(c['time']).timestamp())
                applied += 1
        elif a == 'add':
            if k not in ever:
                punches[k] = [c['employee'].strip(), c['type'].strip().upper(), int(parse_utc(c['time']).timestamp())]
                ever.add(k)
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emp_home:
            byemp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, tz):
        off = int(datetime.fromtimestamp(ts, tz).utcoffset().total_seconds())
        ls = ts + off
        r = ((ls + 180) // 360) * 360
        return ts + (r - ls)

    res = {e: dict(shifts=0, paid=0, ot=0, night=0, pay=Fraction(0)) for e in emp_home}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0)

    def workday(ts, home):
        return datetime.fromtimestamp(ts, ztz[home]).date()

    def inperiod(d):
        return pstart <= d <= pend

    for e, lst in byemp.items():
        home = emp_home[e]
        lst.sort()
        kept = []
        last = None
        for p in lst:
            ts, _, site, pid, dr = p
            if last is not None and last[4] == dr and ts - last[0] <= 300:
                r = rnd(ts, ztz[site])
                if inperiod(workday(r, home)):
                    exc['duplicates_dropped'] += 1
                continue
            kept.append(p)
            last = p
        rk = [(rnd(p[0], ztz[p[2]]), p) for p in kept]
        shifts = []
        pend_in = None

        def open_in(x):
            if inperiod(workday(x[0], home)):
                exc['open_shifts'] += 1
        for r, p in rk:
            if p[4] == 'IN':
                if pend_in is not None:
                    open_in(pend_in)
                pend_in = (r, p)
            else:
                if pend_in is not None and r - pend_in[0] <= 16 * 3600:
                    shifts.append((pend_in, (r, p)))
                    pend_in = None
                else:
                    if pend_in is not None:
                        open_in(pend_in)
                        pend_in = None
                    if inperiod(workday(r, home)):
                        exc['orphan_outs'] += 1
        if pend_in is not None:
            open_in(pend_in)

        items = []
        for (ri, pi), (ro, po) in shifts:
            wd = workday(ri, home)
            if not inperiod(wd):
                continue
            worked = max(0, (ro - ri) // 60)
            paid = worked - 30 if worked > 360 else worked
            tz = ztz[pi[2]]
            night = 0
            for t in range(ri, ro, 60):
                dt = datetime.fromtimestamp(t, tz)
                if dt.hour >= 22 or dt.hour < 6:
                    night += 1
            night = min(night, paid)
            items.append([ri, wd, paid, night, 0, 0])
        items.sort(key=lambda x: x[0])
        daily = {}
        for it in items:
            used = daily.get(it[1], 0)
            reg = max(0, min(it[2], 480 - used))
            it[4] = it[2] - reg  # daily ot
            daily[it[1]] = used + it[2]
        week = {}
        for it in items:
            nd = it[2] - it[4]
            wk = it[1] - timedelta(days=it[1].weekday())
            used = week.get(wk, 0)
            wot = max(0, used + nd - 2400) - max(0, used - 2400)
            it[5] = wot
            week[wk] = used + nd
        rr = rates.get(e, [])
        R = res[e]
        for ri, wd, paid, night, dot, wot in items:
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for ef, v in rr:
                if ef <= wd:
                    rate = v
            if not rate and rr and wd < rr[0][0]:
                rate = rr[0][1]
            R['shifts'] += 1
            R['paid'] += paid
            R['ot'] += ot
            R['night'] += night
            R['pay'] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60

    def money(fr):
        c = (fr * 100 + Fraction(1, 2)).__floor__()
        return '%d.%02d' % divmod(c, 100)

    out = {'period': {'start': period['start'], 'end': period['end']}, 'employees': {}}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, cents=0)
    for e in emp_home:
        R = res[e]
        g = money(R['pay'])
        out['employees'][e] = dict(shifts=R['shifts'], paid_minutes=R['paid'], overtime_minutes=R['ot'],
                                   night_minutes=R['night'], gross=g)
        tot['shifts'] += R['shifts']
        tot['paid_minutes'] += R['paid']
        tot['overtime_minutes'] += R['ot']
        tot['night_minutes'] += R['night']
        tot['cents'] += int(g.replace('.', ''))
    exc['corrections_applied'] = applied
    out['exceptions'] = exc
    out['totals'] = dict(shifts=tot['shifts'], paid_minutes=tot['paid_minutes'],
                         overtime_minutes=tot['overtime_minutes'], night_minutes=tot['night_minutes'],
                         gross='%d.%02d' % divmod(tot['cents'], 100))
    with open(outp, 'w') as f:
        json.dump(out, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
